import { Component, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzSegmentedModule, NzSegmentedOptions } from 'ng-zorro-antd/segmented';
import { HrmControl } from '../shared/hrm-control';

/** hrm-segmented — CVA, options string[] hoặc {label,value}. */
@Component({
  selector: 'hrm-segmented',
  imports: [FormsModule, NzSegmentedModule],
  template: `
    <nz-segmented
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzOptions]="options() ?? []"
      [nzBlock]="block()"
      [nzDisabled]="disabled()"
      [nzSize]="size() === 'sm' ? 'small' : size() === 'lg' ? 'large' : 'default'"></nz-segmented>
  `,
  host: { class: 'hrm-segmented' },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmSegmented), multi: true }],
})
export class HrmSegmented extends HrmControl<string | number> {
  readonly options = input<NzSegmentedOptions>([]);
  readonly size = input<'sm' | 'md' | 'lg'>('md');
  /** block=true kéo giãn các đoạn lấp đầy chiều ngang (kiểu lấp đầy). */
  readonly block = input(false);
}
